<?php
require __DIR__ . '/config.php'; require_login();
$stmt = $pdo->prepare("SELECT c.id,c.title,c.description,c.instructor,e.enrolled_at FROM enrollments e JOIN courses c ON c.id=e.course_id WHERE e.user_id=? ORDER BY e.enrolled_at DESC");
$stmt->execute([$_SESSION['user_id']]); $courses = $stmt->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard | LearnHub</title><link rel="stylesheet" href="style.css"></head><body><header class="topbar"><a class="brand" href="index.php">LearnHub</a><nav><a href="index.php">Home</a><?php if (($_SESSION['role'] ?? '') === 'admin'): ?><a href="admin.php">Admin</a><?php endif; ?><a href="logout.php">Logout</a></nav></header><main class="section"><span class="eyebrow">STUDENT AREA</span><h1>Welcome, <?= h($_SESSION['name']) ?>!</h1><p class="muted">Your enrolled courses appear here.</p><div class="course-grid"><?php if(!$courses): ?><article class="course course-body"><h3>No courses yet</h3><p>Browse the course library and enroll in your first course.</p><a class="text-link" href="index.php#courses">Browse courses →</a></article><?php endif; ?><?php foreach($courses as $c): ?><article class="course course-body"><span class="eyebrow">ENROLLED</span><h3><?= h($c['title']) ?></h3><p><?= h($c['description']) ?></p><small>Instructor: <?= h($c['instructor']) ?></small></article><?php endforeach; ?></div></main></body></html>
